import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';
import { theme } from 'theme';

type LegendPosition = 'center' | 'left' | 'right';
type PaddingRight = '0' | '12' | '20';
type CaptionStyle = 'default' | 'compact';
type FontWeight = 'bold' | 'medium';
type FontType = 'heading' | 'paragraph';
type LegendChartType = 'line' | 'bar' | 'extended-bar';
type PointStyle =
  | 'square'
  | 'circle'
  | 'triangle'
  | 'smallLine'
  | 'line'
  | 'roundedRectangle'
  | 'lineThicker'
  | 'roundedThicker'
  | 'rectRot';

interface StyledCaptionProps {
  $legendPosition?: LegendPosition;
  $paddingRight?: PaddingRight;
  $captionStyle?: CaptionStyle;
}

export const StyledCaption = styled('div', {
  shouldForwardProp: (propName) =>
    !['$legendPosition', '$paddingRight', '$captionStyle'].includes(propName),
})<StyledCaptionProps>(
  ({ $legendPosition, $paddingRight, $captionStyle = 'default' }) => ({
    display: 'flex',
    justifyContent: 'center',
    ...($legendPosition === 'center' && { justifyContent: 'center' }),
    ...($legendPosition === 'left' && { justifyContent: 'flex-start' }),
    ...($legendPosition === 'right' && { justifyContent: 'flex-end' }),
    ...($paddingRight === '12' && { paddingRight: '12px' }),
    ...($paddingRight === '20' && { paddingRight: '20px' }),
    ...($paddingRight === '0' && { paddingRight: '0px' }),
    ...($captionStyle === 'default' && {
      flexWrap: 'wrap',
      width: '100%',
    }),
    ...($captionStyle === 'compact' && {
      flexWrap: 'nowrap',
      width: '100%',
    }),
  }),
);

export const StyledTextCaption = styled.div({
  display: 'flex',
  alignItems: 'center',
  marginRight: '8px',
});

interface StyledTextProps {
  $fontWeight?: FontWeight;
  $font?: FontType;
}

export const StyledText = styled(Paragraph, {
  shouldForwardProp: (propName) =>
    !['$fontWeight', '$font'].includes(propName),
})<StyledTextProps>(({ $fontWeight, $font }) => ({
  margin: '0.7rem 1rem 0.75rem 0',
  ...($fontWeight === 'bold' && { fontWeight: 'bold !important' }),
  ...($fontWeight === 'medium' && { fontWeight: '600' }),
  ...($font === 'heading' && { fontFamily: theme.fonts.heading }),
  ...($font === 'paragraph' && { fontFamily: theme.fonts.paragraph }),
}));

interface StyledColorIndicatorProps {
  $chartType?: LegendChartType;
  $pointStyle?: PointStyle;
}

const pointStyleMap: Record<PointStyle, object> = {
  square: { borderRadius: '20%' },
  circle: { borderRadius: '50%' },
  triangle: {
    width: '14px',
    height: '12px',
    clipPath: 'polygon(50% 0, 0 100%, 100% 100%)',
  },
  smallLine: {
    height: '2px',
    borderRadius: '4px',
  },
  line: {
    height: '4px',
    borderRadius: '4px',
  },
  roundedRectangle: {
    borderRadius: '4px',
    width: '24px',
    height: '12px',
  },
  lineThicker: {
    height: '12px',
    width: '24px',
    borderRadius: '4px',
    marginBottom: '2px',
  },
  roundedThicker: {
    height: '12px',
    width: '24px',
    borderRadius: '8px',
    marginBottom: '2px',
  },
  rectRot: {
    width: '12px',
    height: '12px',
    transform: 'rotate(-45deg)',
  },
};

export const StyledColorIndicator = styled('span', {
  shouldForwardProp: (propName) =>
    !['$chartType', '$pointStyle'].includes(propName),
})<StyledColorIndicatorProps>(({ $chartType, $pointStyle }) => ({
  display: 'inline-block',
  width: '16px',
  marginRight: '8px',
  ...($chartType === 'line' && { height: '4px' }),
  ...($chartType === 'bar' && { height: '16px' }),
  ...($chartType === 'extended-bar' && {
    height: '12px',
    width: '24px',
  }),
  ...($pointStyle != null && pointStyleMap[$pointStyle]),
}));
